package com.nexodb.tools;

import com.nexodb.db.MigrationService;import com.nexodb.util.*;import java.io.IOException;import java.nio.file.*;import java.time.*;import java.util.*;

/** Team review metadata stored beside SQL sources. Never stores SQL, connection data or credentials. */
public final class TeamWorkspaceService {
 public enum Decision {PENDING,APPROVED,CHANGES_REQUESTED}
 public record Review(String file,String checksum,Decision decision,String reviewer,String comment,Instant time){}
 public record Activity(LocalDate day,String action,int count){}
 private final Path root,metadata,reviewsFile,activityFile;
 public TeamWorkspaceService(Path root)throws IOException{this.root=root.toAbsolutePath().normalize();if(!Files.isDirectory(this.root))throw new IOException("La carpeta del proyecto no existe.");metadata=this.root.resolve(".adisdb");reviewsFile=metadata.resolve("team-reviews.properties");activityFile=metadata.resolve("team-activity.properties");}
 public Path root(){return root;}
 public List<Review> reviews()throws IOException{Properties p=AtomicProperties.read(reviewsFile);List<Review> result=new ArrayList<>();int count=number(p.getProperty("count"));for(int i=0;i<count;i++)try{result.add(new Review(p.getProperty(i+".file",""),p.getProperty(i+".checksum",""),Decision.valueOf(p.getProperty(i+".decision","PENDING")),p.getProperty(i+".reviewer",""),p.getProperty(i+".comment",""),Instant.parse(p.getProperty(i+".time",Instant.EPOCH.toString()))));}catch(Exception ignored){}return List.copyOf(result);}
 public List<Review> migrationReviews()throws Exception{Map<String,Review> saved=new HashMap<>();for(Review review:reviews())saved.put(review.file(),review);List<Review> result=new ArrayList<>();for(var migration:MigrationService.discover(root)){Review review=saved.get(migration.file().getFileName().toString());if(review==null||!review.checksum().equals(migration.checksum()))result.add(new Review(migration.file().getFileName().toString(),migration.checksum(),Decision.PENDING,"","",Instant.EPOCH));else result.add(review);}return List.copyOf(result);}
 public void review(String file,String checksum,Decision decision,String reviewer,String comment)throws IOException{if(reviewer==null||reviewer.isBlank())throw new IllegalArgumentException("Indica quién realiza la revisión.");List<Review> values=new ArrayList<>(reviews());values.removeIf(item->item.file().equals(file));values.add(new Review(file,checksum,decision,reviewer.trim(),Objects.toString(comment,""),Instant.now()));saveReviews(values);record("REVIEW_"+decision.name());}
 private void saveReviews(List<Review> values)throws IOException{Properties p=new Properties();p.setProperty("count",Integer.toString(values.size()));for(int i=0;i<values.size();i++){Review r=values.get(i);p.setProperty(i+".file",r.file());p.setProperty(i+".checksum",r.checksum());p.setProperty(i+".decision",r.decision().name());p.setProperty(i+".reviewer",r.reviewer());p.setProperty(i+".comment",r.comment());p.setProperty(i+".time",r.time().toString());}AtomicProperties.write(reviewsFile,p);}
 public synchronized void record(String action)throws IOException{Properties p=AtomicProperties.read(activityFile);String key=LocalDate.now()+"."+action.replaceAll("[^A-Z0-9_-]","_").toUpperCase(Locale.ROOT);p.setProperty(key,Integer.toString(number(p.getProperty(key))+1));AtomicProperties.write(activityFile,p);}
 public List<Activity> activity()throws IOException{Properties p=AtomicProperties.read(activityFile);List<Activity> result=new ArrayList<>();for(String key:p.stringPropertyNames()){int dot=key.indexOf('.');if(dot<0)continue;try{result.add(new Activity(LocalDate.parse(key.substring(0,dot)),key.substring(dot+1),number(p.getProperty(key))));}catch(Exception ignored){}}return result.stream().sorted(Comparator.comparing(Activity::day).reversed().thenComparing(Activity::action)).toList();}
 public String report()throws Exception{List<Review> reviews=migrationReviews();long approved=reviews.stream().filter(r->r.decision()==Decision.APPROVED).count(),pending=reviews.stream().filter(r->r.decision()==Decision.PENDING).count(),changes=reviews.stream().filter(r->r.decision()==Decision.CHANGES_REQUESTED).count();StringBuilder out=new StringBuilder("# Estado del proyecto SQL\n\nCarpeta: `").append(root.getFileName()).append("`\n\n- Migraciones aprobadas: ").append(approved).append("\n- Pendientes: ").append(pending).append("\n- Cambios solicitados: ").append(changes).append("\n\n| Archivo | Estado | Revisor | Comentario |\n|---|---|---|---|\n");for(Review r:reviews)out.append('|').append(escape(r.file())).append('|').append(r.decision()).append('|').append(escape(r.reviewer())).append('|').append(escape(r.comment())).append("|\n");out.append("\n## Actividad local agregada\n\n| Día | Acción | Cantidad |\n|---|---|---:|\n");for(Activity a:activity())out.append('|').append(a.day()).append('|').append(a.action()).append('|').append(a.count()).append("|\n");return out.toString();}
 private static int number(String value){try{return Math.max(0,Integer.parseInt(Objects.toString(value,"0")));}catch(Exception ignored){return 0;}}private static String escape(String value){return Objects.toString(value,"").replace("|","\\|").replace("\r"," ").replace("\n"," ");}
}
